use anyhow::{bail,Context,Result};use std::path::{Path,PathBuf};
pub fn resolve(root:&Path,requested:&str,must_exist:bool)->Result<PathBuf>{let root=root.canonicalize().context("resolve root")?;let raw=PathBuf::from(requested.trim());if requested.trim().is_empty(){bail!("path required")};let candidate=if raw.is_absolute(){raw}else{root.join(raw)};if must_exist{let p=candidate.canonicalize().context("resolve path")?;if !p.starts_with(&root){bail!("path escapes workspace")};return Ok(p)}let parent=candidate.parent().ok_or_else(||anyhow::anyhow!("path has no parent"))?;let mut existing=parent;while !existing.exists(){existing=existing.parent().ok_or_else(||anyhow::anyhow!("no existing ancestor"))?}let canon=existing.canonicalize()?;if !canon.starts_with(&root){bail!("path escapes workspace")};Ok(candidate)}
